@Component("experiment-handler")
@ProcessingGroup("experiment-processing-group")
public class ExperimentEventHandler {
	
	// core constructor
	ExperimentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateExperimentEvent
     */
    @EventHandler
    public void handle( CreateExperimentEvent event) {
        entityManager.persist(new Experiment(event.getExperimentId(), event.getName(), event.getHypothesis(), event.getStartDate(), event.getEndDate(), event.getCampaign(), event.getVariants(), event.getStatus()));
    }

    /*
     * @param	event UpdateExperimentEvent
     */
    @EventHandler
    public Experiment handle( UpdateExperimentEvent event) {
    	entityManager.merge(new Experiment(event.getExperimentId(), event.getName(), event.getHypothesis(), event.getStartDate(), event.getEndDate(), event.getCampaign(), event.getVariants(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteExperimentEvent
     */
    @EventHandler
    public void on( DeleteExperimentEvent event) {
    	Experiment entity = new Experiment();
   
    	// ------------------------------------------
    	// apply the ExperimentId
    	// ------------------------------------------
    	entity.setExperimentId( event.getExperimentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ExperimentRepository experimentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ExperimentEventHandler.class.getName());

}
